// Generates css/<theme>.css, tailwind/preset.cjs, swift/IsDeadTokens.swift from tokens/*.json
import fs from "node:fs"; import path from "node:path";
const root = path.dirname(path.dirname(new URL(import.meta.url).pathname));
const themes = ["calendly", "superhuman", "wisprflow"].map(n => JSON.parse(fs.readFileSync(`${root}/tokens/${n}.json`, "utf8")));
const kebab = s => s.replace(/[A-Z]/g, m => "-" + m.toLowerCase());
const groups = ["color", "radius", "space", "shadow", "type", "control"];
for (const t of themes) {
  const faces = Object.entries(t.font.files).map(([fam, f]) =>
    `@font-face{font-family:"IsDead ${fam}";src:url("../fonts/${f}") format("woff2");font-weight:100 900;font-style:normal;font-display:swap}`).join("\n");
  const vars = groups.flatMap(g => Object.entries(t[g]).map(([k, v]) => `  --ids-${g}-${kebab(k)}:${v};`));
  vars.push(`  --ids-font-sans:"IsDead ${t.font.sans}",system-ui,-apple-system,"Segoe UI",sans-serif;`);
  vars.push(`  --ids-font-display:"IsDead ${t.font.display}",var(--ids-font-sans);`);
  vars.push(`  --ids-font-mono:${t.font.mono};`);
  vars.push(`  --ids-gradient-hero:linear-gradient(160deg,${t.color.heroFrom} 0%,${t.color.heroMid} 50%,${t.color.heroTo} 100%);`);
  fs.writeFileSync(`${root}/css/${t.name}.css`, `/* generated by scripts/build.mjs from tokens/${t.name}.json. Do not edit. */\n${faces}\n:root,[data-ids-theme="${t.name}"]{\n${vars.join("\n")}\n}\n`);
}
// Tailwind preset: theme values point at CSS variables so one preset serves every theme.
const t0 = themes[0];
const v = (g, o) => Object.fromEntries(Object.keys(o).map(k => [kebab(k), `var(--ids-${g}-${kebab(k)})`]));
const preset = { theme: { extend: { colors: v("color", t0.color), borderRadius: v("radius", t0.radius), spacing: v("space", t0.space), boxShadow: v("shadow", t0.shadow),
  fontSize: Object.fromEntries(["xs","sm","md","lg","xl","2xl","3xl","4xl"].map(k => [k, `var(--ids-type-${k})`])),
  fontFamily: { sans: ["var(--ids-font-sans)"], display: ["var(--ids-font-display)"], mono: ["var(--ids-font-mono)"] } } } };
fs.writeFileSync(`${root}/tailwind/preset.cjs`, `// generated by scripts/build.mjs\nmodule.exports = ${JSON.stringify(preset, null, 2)};\n`);
// Swift
const hex = h => { if (h.startsWith("rgba")) { const [r,g,b,a] = h.match(/[\d.]+/g).map(Number); return `Color(red: ${(r/255).toFixed(3)}, green: ${(g/255).toFixed(3)}, blue: ${(b/255).toFixed(3)}, opacity: ${a})`; }
  const n = parseInt(h.slice(1), 16); return `Color(red: ${((n>>16&255)/255).toFixed(3)}, green: ${((n>>8&255)/255).toFixed(3)}, blue: ${((n&255)/255).toFixed(3)})`; };
const px = s => parseFloat(s);
let sw = `// generated by scripts/build.mjs from tokens/*.json. Do not edit.\n// Register the fonts in fonts/<theme>/ (ATSApplicationFontsPath or CTFontManagerRegisterFontsForURL).\nimport SwiftUI\n\npublic struct IsDeadTheme {\n  public let name: String\n  public let fontSans: String\n  public let fontDisplay: String\n`;
const ck = Object.keys(t0.color);
sw += ck.map(k => `  public let ${k}: Color`).join("\n") + "\n" + Object.keys(t0.radius).map(k => `  public let radius${k[0].toUpperCase()+k.slice(1)}: CGFloat`).join("\n") + "\n" + ["xs","sm","md","lg","xl","2xl","3xl","4xl"].map(k=>`  public let text${k.toUpperCase().replace("2XL","2xl").replace("3XL","3xl").replace("4XL","4xl")}: CGFloat`).join("\n") + "\n  public let controlHeight: CGFloat\n}\n\npublic extension IsDeadTheme {\n";
for (const t of themes.filter(t => t.name !== "calendly")) {
  const cs = Object.keys(t0.color).map(k => `    ${k}: ${hex(t.color[k] ?? t.color.accent)}`);
  sw += `  static let ${t.name} = IsDeadTheme(\n    name: "${t.name}", fontSans: "${t.font.sans}", fontDisplay: "${t.font.display}",\n${cs.join(",\n")},\n${Object.keys(t0.radius).map(k=>`    radius${k[0].toUpperCase()+k.slice(1)}: ${t.radius[k]==="9999px"?999:px(t.radius[k])}`).join(",\n")},\n${["xs","sm","md","lg","xl","2xl","3xl","4xl"].map(k=>`    text${k.toUpperCase().replace("2XL","2xl").replace("3XL","3xl").replace("4XL","4xl")}: ${px(t.type[k])}`).join(",\n")},\n    controlHeight: ${px(t.control.height)}\n  )\n`;
}
sw += "}\n";
fs.mkdirSync(`${root}/swift`, { recursive: true });
fs.writeFileSync(`${root}/swift/IsDeadTokens.swift`, sw);
console.log("built", themes.map(t => t.name).join(", "));
